-- ---------------------------------------------------------------------
-- 020_demo_users_creators.sql
--
-- Demo population for the Zusty marketplace: brand accounts, creator
-- accounts and the creator profiles the home screen renders.
--
-- Seeds:
--   users                     1001-1020  (account_type = 'brand',   20 rows)
--   users                     2001-2045  (account_type = 'creator', 45 rows)
--   creators                  101-145    (user_id = 2000 + (id - 100))
--   creator_categories        1-3 rows per creator (primary + secondary)
--   creator_social_accounts   3001-3118  (1-4 platforms per creator)
--
-- Home-screen guarantees:
--   * 11 approved creators with is_featured = 1   -> "Featured"
--   * 25 approved creators with rating_avg >= 4.50
--     and rating_count >= 20                      -> "Top Creators"
--   * 9  creators created within the last 30 days -> "New on Zusty"
--   * all 16 categories, 4 follower tiers and 18 cities represented
--
-- Every brand, person and handle here is invented, because these rows end
-- up in store screenshots: creator handles end in ".demo" and brand
-- websites use the reserved ".example" domain, so nothing names or links to
-- a real business or social account.
--
-- Every statement is idempotent, so re-running the file is a no-op.
-- Password for every seeded account is "Password123!".
-- ---------------------------------------------------------------------

SET NAMES utf8mb4;

