INSERT INTO `creators`
  (`id`, `user_id`, `handle`, `display_name`, `headline`, `about`, `cover_image_url`,
   `primary_category_id`, `city`, `state`, `country`, `gender`, `date_of_birth`,
   `languages`, `price_min`, `price_max`, `currency`, `rating_avg`, `rating_count`,
   `followers_total`, `platform_followers`, `posts_count`, `collabs_count`,
   `completion_rate`, `response_time_hours`, `availability_status`, `is_verified`,
   `verified_at`, `is_featured`, `featured_until`, `status`, `rejection_reason`,
   `approved_by`, `approved_at`, `profile_score`, `search_boost`, `meta_title`,
   `meta_description`, `created_at`, `updated_at`)
VALUES
  (101, 2001, 'aanya.kapoor.demo', 'Aanya Kapoor', 'Lifestyle & everyday-home creator', 'I document the small stuff that makes a Mumbai 1BHK feel like home - Sunday reorganising, budget decor swaps, and the skincare and kitchen products that actually survive my routine. Eight years in advertising taught me how a brief works, so expect clean deliverables, on-time drafts and captions that sound like a person, not a press note.', 'https://picsum.photos/seed/cover-aanya-kapoor/1200/480', 1, 'Mumbai', 'Maharashtra', 'India', 'female', '1996-04-12', '["English", "Hindi", "Marathi"]', 17500.00, 65000.00, 'INR', 4.80, 64, 86500, 479, 159, 72, 96.60, 12, 'available', 1, DATE_SUB(NOW(), INTERVAL 390 DAY), 1, DATE_ADD(NOW(), INTERVAL 45 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 393 DAY), 95, 1.45, 'Aanya Kapoor (@aanya.kapoor.demo) - Lifestyle Creator in Mumbai | Zusty', 'I document the small stuff that makes a Mumbai 1BHK feel like home. Lifestyle collaborations from Rs.17,500.', DATE_SUB(NOW(), INTERVAL 395 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (102, 2002, 'rhea.menon.demo', 'Rhea Menon', 'Slow living in Bengaluru', 'Mornings on the balcony, filter coffee, and a running experiment in owning less. My audience is 25-34, mostly women in metros, and they buy what I use rather than what I announce. I take a maximum of four brand collaborations a month so the feed never turns into a catalogue.', 'https://picsum.photos/seed/cover-thedailyrhea/1200/480', 1, 'Bengaluru', 'Karnataka', 'India', 'female', '1994-09-03', '["English", "Hindi", "Malayalam"]', 93000.00, 180000.00, 'INR', 4.70, 51, 248000, 989, 224, 54, 96.40, 18, 'available', 1, DATE_SUB(NOW(), INTERVAL 367 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 370 DAY), 83, 1.25, 'Rhea Menon (@rhea.menon.demo) - Lifestyle Creator in Bengaluru | Zusty', 'Mornings on the balcony, filter coffee, and a running experiment in owning less. Lifestyle collaborations from Rs.93,000.', DATE_SUB(NOW(), INTERVAL 372 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (103, 2003, 'kabir.sethi.demo', 'Kabir Sethi', 'Delhi day-in-the-life reels', 'Twenty-something in Delhi shooting honest day-in-the-life reels - metro commutes, Rs.200 lunches, hostel-room makeovers. Small but high-trust audience: my DMs get more questions than my comments get likes. Best fit for brands that want genuine first-time-user reactions.', 'https://picsum.photos/seed/cover-kabirlivesit/1200/480', 1, 'Delhi', 'Delhi', 'India', 'male', '1999-01-22', '["Hindi", "English"]', 6000.00, 9800.00, 'INR', 4.30, 11, 7400, 316, 187, 15, 92.60, 24, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 208 DAY), 75, 1.00, 'Kabir Sethi (@kabir.sethi.demo) - Lifestyle Creator in Delhi | Zusty', 'Twenty-something in Delhi shooting honest day-in-the-life reels. Lifestyle collaborations from Rs.6,000.', DATE_SUB(NOW(), INTERVAL 210 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (104, 2004, 'meher.nagpal.demo', 'Meher Nagpal', 'Occasion wear, styled for real bodies', 'Nine years of styling shoots for Delhi labels turned into a full-time page about dressing for weddings, work and everything between - on real budgets and real body types. I shoot lookbooks in-house with my own team, so brands get campaign-grade stills along with the reel.', 'https://picsum.photos/seed/cover-meherstylediary/1200/480', 2, 'Delhi', 'Delhi', 'India', 'female', '1993-06-18', '["Hindi", "English", "Punjabi"]', 460000.00, 900000.00, 'INR', 4.90, 118, 812000, 2718, 413, 123, 100.00, 2, 'available', 1, DATE_SUB(NOW(), INTERVAL 405 DAY), 1, DATE_ADD(NOW(), INTERVAL 90 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 408 DAY), 98, 1.60, 'Meher Nagpal (@meher.nagpal.demo) - Fashion Creator in Delhi | Zusty', 'Nine years of styling shoots for Delhi labels turned into a full-time page about dressing for weddings, work and everything between. Fashion collaborations from Rs.460,000.', DATE_SUB(NOW(), INTERVAL 410 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY)),
  (105, 2005, 'ishita.rane.demo', 'Ishita Rane', 'Saree styling and handloom stories', 'I drape one saree eleven ways and tell you which weaver made it. Paithani, ilkal, jamdani - the page has become a small archive of Indian handloom, and my audience travels to buy directly from clusters. Handloom, jewellery and ethnic-wear brands see the strongest conversion here.', 'https://picsum.photos/seed/cover-draped-by-ishita/1200/480', 2, 'Pune', 'Maharashtra', 'India', 'female', '1997-11-09', '["Marathi", "Hindi", "English"]', 15000.00, 57000.00, 'INR', 4.60, 37, 63200, 305, 249, 43, 93.20, 3, 'busy', 1, DATE_SUB(NOW(), INTERVAL 315 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 318 DAY), 86, 1.20, 'Ishita Rane (@ishita.rane.demo) - Fashion Creator in Pune | Zusty', 'I drape one saree eleven ways and tell you which weaver made it. Fashion collaborations from Rs.15,000.', DATE_SUB(NOW(), INTERVAL 320 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY)),
  (106, 2006, 'arjun.malhotra.demo', 'Arjun Malhotra', 'Menswear that fits Indian frames', 'Menswear fit guides for the 5''7" Indian man - what to buy, what to tailor, what to skip. Weekly try-on hauls, sneaker breakdowns and one brutally honest quality teardown every month. If a stitch is bad I will say so on camera, which is exactly why the recommendations land.', 'https://picsum.photos/seed/cover-arjunfitsdaily/1200/480', 2, 'Mumbai', 'Maharashtra', 'India', 'male', '1995-03-27', '["English", "Hindi"]', 84000.00, 260000.00, 'INR', 4.40, 29, 176500, 674, 302, 36, 91.80, 4, 'available', 1, DATE_SUB(NOW(), INTERVAL 280 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 283 DAY), 87, 1.00, 'Arjun Malhotra (@arjun.malhotra.demo) - Fashion Creator in Mumbai | Zusty', 'Menswear fit guides for the 5''7" Indian man. Fashion collaborations from Rs.84,000.', DATE_SUB(NOW(), INTERVAL 285 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY)),
  (107, 2007, 'tanvi.deshpande.demo', 'Tanvi Deshpande', 'Offbeat India, one trail at a time', 'Based in Goa, on the road twenty days a month. Spiti in a hatchback, Meghalaya in monsoon, the Konkan coast on a scooter - always with real costs, real permits and the homestay owner''s number in the caption. Travel boards, stays and gear brands get itinerary-led content, not just pretty drone shots.', 'https://picsum.photos/seed/cover-tanvitrails/1200/480', 3, 'Goa', 'Goa', 'India', 'female', '1994-12-05', '["English", "Hindi", "Marathi", "Konkani"]', 93000.00, 280000.00, 'INR', 4.80, 73, 314000, 1113, 360, 81, 97.60, 6, 'available', 1, DATE_SUB(NOW(), INTERVAL 383 DAY), 1, DATE_ADD(NOW(), INTERVAL 60 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 386 DAY), 94, 1.50, 'Tanvi Deshpande (@tanvi.deshpande.demo) - Travel Creator in Goa | Zusty', 'Based in Goa, on the road twenty days a month. Travel collaborations from Rs.93,000.', DATE_SUB(NOW(), INTERVAL 388 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (108, 2008, 'zoya.qureshi.demo', 'Zoya Qureshi', 'Solo female travel on a budget', 'Solo across nineteen states on sleeper trains and shared jeeps, mostly under Rs.1,500 a day. Half my content is safety logistics - which platform, which hostel, which bus stand to avoid after dark - because that is what my audience actually writes in for.', 'https://picsum.photos/seed/cover-backpackwithzoya/1200/480', 3, 'Jaipur', 'Rajasthan', 'India', 'female', '1998-08-14', '["Hindi", "English", "Urdu"]', 22500.00, 45000.00, 'INR', 4.50, 26, 48900, 368, 318, 29, 95.00, 8, 'available', 1, DATE_SUB(NOW(), INTERVAL 260 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 263 DAY), 80, 1.15, 'Zoya Qureshi (@zoya.qureshi.demo) - Travel Creator in Jaipur | Zusty', 'Solo across nineteen states on sleeper trains and shared jeeps, mostly under Rs.1,500 a day. Travel collaborations from Rs.22,500.', DATE_SUB(NOW(), INTERVAL 265 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (109, 2009, 'nikhil.bhandari.demo', 'Nikhil Bhandari', 'Himalayan road trips and overlanding', 'Overlanding films from Ladakh, Zanskar and Sach Pass, shot on a modified Thar with a two-person crew. Long-form on YouTube, cutdowns on Instagram. Automotive, gear and telecom brands use my routes as a proving ground because nothing fake survives 4,000 metres.', 'https://picsum.photos/seed/cover-nomadnikhil/1200/480', 3, 'Chandigarh', 'Chandigarh', 'India', 'male', '1992-02-11', '["Hindi", "English", "Punjabi"]', 460000.00, 825000.00, 'INR', 4.40, 44, 640000, 2142, 490, 48, 94.80, 12, 'available', 1, DATE_SUB(NOW(), INTERVAL 350 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 353 DAY), 81, 1.00, 'Nikhil Bhandari (@nikhil.bhandari.demo) - Travel Creator in Chandigarh | Zusty', 'Overlanding films from Ladakh, Zanskar and Sach Pass, shot on a modified Thar with a two-person crew. Travel collaborations from Rs.460,000.', DATE_SUB(NOW(), INTERVAL 355 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (110, 2010, 'aditi.ranganathan.demo', 'Aditi Ranganathan', 'South Indian kitchen, modern method', 'Trained at a hotel school in Chennai, now cooking my grandmother''s recipes with a thermometer and a scale. Kuzhambu ratios, dosa batter fermentation charts, and one restaurant-style dish demystified every week. Appliance and staples brands love the format because the recipe genuinely works the first time.', 'https://picsum.photos/seed/cover-chefaditi-eats/1200/480', 4, 'Chennai', 'Tamil Nadu', 'India', 'female', '1991-07-30', '["Tamil", "English", "Hindi"]', 75000.00, 220000.00, 'INR', 4.90, 96, 268000, 1083, 157, 101, 96.80, 18, 'available', 1, DATE_SUB(NOW(), INTERVAL 396 DAY), 1, DATE_ADD(NOW(), INTERVAL 30 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 399 DAY), 97, 1.40, 'Aditi Ranganathan (@aditi.ranganathan.demo) - Food Creator in Chennai | Zusty', 'Trained at a hotel school in Chennai, now cooking my grandmother''s recipes with a thermometer and a scale. Food collaborations from Rs.75,000.', DATE_SUB(NOW(), INTERVAL 401 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (111, 2011, 'sourav.dutta.demo', 'Sourav Dutta', 'Kolkata street food and para cafes', 'Kathi rolls in Park Circus, telebhaja in Shyambazar, and every new cafe in the para that lasts more than a month. Bilingual captions in Bangla and English, prices always on screen. Food delivery apps and QSR launches see the sharpest local pickup here.', 'https://picsum.photos/seed/cover-kolkatakhaanapeena/1200/480', 4, 'Kolkata', 'West Bengal', 'India', 'male', '1996-10-19', '["Bengali", "Hindi", "English"]', 17500.00, 57000.00, 'INR', 4.20, 14, 41200, 451, 124, 17, 89.40, 24, 'busy', 0, NULL, 0, NULL, 'pending_review', NULL, NULL, NULL, 65, 0.80, 'Sourav Dutta (@sourav.dutta.demo) - Food Creator in Kolkata | Zusty', 'Kathi rolls in Park Circus, telebhaja in Shyambazar, and every new cafe in the para that lasts more than a month. Food collaborations from Rs.17,500.', DATE_SUB(NOW(), INTERVAL 52 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY)),
  (112, 2012, 'preeti.ahuja.demo', 'Preeti Ahuja', 'Awadhi home cooking, small batch', 'Newly on Zusty but four years deep into cooking Awadhi food in a Lucknow home kitchen - galouti without a tandoor, sheermal in a kadhai, biryani for two. Small audience, very high save rate, and a comment section that treats the recipes like family property.', 'https://picsum.photos/seed/cover-masalamemoirs/1200/480', 4, 'Lucknow', 'Uttar Pradesh', 'India', 'female', '2000-05-08', '["Hindi", "English"]', 5000.00, 12200.00, 'INR', 4.60, 6, 9100, 146, 140, 13, 95.20, 2, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 16 DAY), 68, 1.00, 'Preeti Ahuja (@preeti.ahuja.demo) - Food Creator in Lucknow | Zusty', 'Newly on Zusty but four years deep into cooking Awadhi food in a Lucknow home kitchen. Food collaborations from Rs.5,000.', DATE_SUB(NOW(), INTERVAL 18 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY)),
  (113, 2013, 'varun.iyer.demo', 'Varun Iyer', 'Strength coach - evidence first', 'Certified strength coach with 400+ online clients. No transformation bait, no fat-burner sponsorships - just programming, form breakdowns and a monthly myth-busting series citing actual papers. Supplement brands are vetted with lab reports before I say yes.', 'https://picsum.photos/seed/cover-liftwithvarun/1200/480', 5, 'Bengaluru', 'Karnataka', 'India', 'male', '1993-01-16', '["English", "Hindi", "Tamil"]', 102000.00, 280000.00, 'INR', 4.70, 58, 192000, 719, 210, 66, 97.40, 3, 'available', 1, DATE_SUB(NOW(), INTERVAL 361 DAY), 1, DATE_ADD(NOW(), INTERVAL 75 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 364 DAY), 93, 1.55, 'Varun Iyer (@varun.iyer.demo) - Fitness Creator in Bengaluru | Zusty', 'Certified strength coach with 400+ online clients. Fitness collaborations from Rs.102,000.', DATE_SUB(NOW(), INTERVAL 366 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY)),
  (114, 2014, 'sanaya.kotak.demo', 'Sanaya Kotak', 'Home workouts for busy women', 'Twenty-minute follow-along workouts you can do between a work call and the school pickup - no equipment beyond a mat and a chair. Postpartum-safe progressions are the most requested series on the page, and activewear brands see high repeat purchase from this audience.', 'https://picsum.photos/seed/cover-fitwithsanaya/1200/480', 5, 'Ahmedabad', 'Gujarat', 'India', 'female', '1997-04-02', '["Gujarati", "Hindi", "English"]', 25000.00, 45000.00, 'INR', 4.40, 22, 57400, 358, 200, 25, 94.80, 4, 'available', 1, DATE_SUB(NOW(), INTERVAL 235 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 238 DAY), 86, 1.00, 'Sanaya Kotak (@sanaya.kotak.demo) - Fitness Creator in Ahmedabad | Zusty', 'Twenty-minute follow-along workouts you can do between a work call and the school pickup. Fitness collaborations from Rs.25,000.', DATE_SUB(NOW(), INTERVAL 240 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (115, 2015, 'harmeet.singh.demo', 'Harmeet Singh', 'Personal trainer and nutrition coach', 'Gym floor coaching in Chandigarh, mostly beginner strength and fat loss for desk-job clients. Building out the content side of the practice with weekly form-check clips and a Punjabi-language nutrition explainer series.', 'https://picsum.photos/seed/cover-coachharmeet/1200/480', 5, 'Chandigarh', 'Chandigarh', 'India', 'male', '1995-09-25', '["Punjabi", "Hindi", "English"]', 3000.00, 9800.00, 'INR', 0.00, 0, 5600, 241, 211, 1, 100.00, 6, 'available', 0, NULL, 0, NULL, 'rejected', 'Profile rejected: the linked Instagram account could not be verified as belonging to the applicant and the ID document had expired. Re-apply with a current government ID and complete the in-app handle verification.', NULL, NULL, 41, 0.80, 'Harmeet Singh (@harmeet.singh.demo) - Fitness Creator in Chandigarh | Zusty', 'Gym floor coaching in Chandigarh, mostly beginner strength and fat loss for desk-job clients. Fitness collaborations from Rs.3,000.', DATE_SUB(NOW(), INTERVAL 58 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (116, 2016, 'devansh.gupta.demo', 'Devansh Gupta', 'Consumer tech reviews, no fluff', 'Ex-firmware engineer reviewing phones, laptops and audio the way an engineer would - thermal logs, battery drain tables, and a two-week daily-driver period before any verdict. I publish my testing methodology, and I return review units. Brands that survive this review sell well.', 'https://picsum.photos/seed/cover-techtalkswithdev/1200/480', 6, 'Hyderabad', 'Telangana', 'India', 'male', '1990-11-11', '["English", "Hindi", "Telugu"]', 340000.00, 900000.00, 'INR', 4.80, 132, 905000, 2921, 460, 137, 96.60, 8, 'available', 1, DATE_SUB(NOW(), INTERVAL 410 DAY), 1, DATE_ADD(NOW(), INTERVAL 45 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 413 DAY), 96, 1.45, 'Devansh Gupta (@devansh.gupta.demo) - Tech Creator in Hyderabad | Zusty', 'Ex-firmware engineer reviewing phones, laptops and audio the way an engineer would. Tech collaborations from Rs.340,000.', DATE_SUB(NOW(), INTERVAL 415 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (117, 2017, 'neha.kulkarni.demo', 'Neha Kulkarni', 'Smart home and everyday gadgets', 'Setting up a genuinely useful smart home on a middle-class budget - which Rs.1,200 bulb is worth it, which robot vacuum dies in six months. My audience skews women 25-40 who buy the product from the affiliate link the same evening.', 'https://picsum.photos/seed/cover-gadgetgirlneha/1200/480', 6, 'Pune', 'Maharashtra', 'India', 'female', '1996-06-21', '["Marathi", "Hindi", "English"]', 20000.00, 57000.00, 'INR', 4.50, 31, 72400, 507, 276, 37, 94.00, 12, 'busy', 1, DATE_SUB(NOW(), INTERVAL 293 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 296 DAY), 80, 1.20, 'Neha Kulkarni (@neha.kulkarni.demo) - Tech Creator in Pune | Zusty', 'Setting up a genuinely useful smart home on a middle-class budget. Tech collaborations from Rs.20,000.', DATE_SUB(NOW(), INTERVAL 298 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (118, 2018, 'siddharth.nair.demo', 'Siddharth Nair', 'Developer career and dev tools', 'Backend engineer teaching system design, interview prep and the tools that actually earn their subscription. Long-form builds on YouTube, short debugging clips on Instagram. Dev-tool and edtech brands reach a working-engineer audience here, not a student one.', 'https://picsum.photos/seed/cover-codewithsiddharth/1200/480', 6, 'Kochi', 'Kerala', 'India', 'male', '1994-03-09', '["Malayalam", "English", "Hindi"]', 102000.00, 260000.00, 'INR', 4.60, 40, 143000, 750, 317, 47, 96.20, 18, 'available', 1, DATE_SUB(NOW(), INTERVAL 326 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 329 DAY), 81, 1.25, 'Siddharth Nair (@siddharth.nair.demo) - Tech Creator in Kochi | Zusty', 'Backend engineer teaching system design, interview prep and the tools that actually earn their subscription. Tech collaborations from Rs.102,000.', DATE_SUB(NOW(), INTERVAL 331 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY)),
  (119, 2019, 'simran.bedi.demo', 'Simran Bedi', 'Skincare that respects the barrier', 'Four weeks of patch-testing before any skincare review, and full ingredient lists on screen every time. Combination skin, Delhi pollution, and a very vocal comment section that catches greenwashing faster than I do. Skincare launches consistently see their best day-one traffic from this page.', 'https://picsum.photos/seed/cover-glowwithsimran/1200/480', 7, 'Delhi', 'Delhi', 'India', 'female', '1995-08-17', '["Hindi", "English", "Punjabi"]', 111000.00, 280000.00, 'INR', 4.90, 88, 226000, 784, 362, 96, 100.00, 24, 'available', 1, DATE_SUB(NOW(), INTERVAL 387 DAY), 1, DATE_ADD(NOW(), INTERVAL 90 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 390 DAY), 92, 1.60, 'Simran Bedi (@simran.bedi.demo) - Beauty Creator in Delhi | Zusty', 'Four weeks of patch-testing before any skincare review, and full ingredient lists on screen every time. Beauty collaborations from Rs.111,000.', DATE_SUB(NOW(), INTERVAL 392 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY)),
  (120, 2020, 'kavya.reddy.demo', 'Kavya Reddy', 'Makeup for deeper Indian skin tones', 'Shade matching for medium-to-deep Indian skin, because half the launches still stop three shades too light. Bridal looks in Telugu, everyday looks in English, and a running shade-availability tracker that brands quietly use as feedback.', 'https://picsum.photos/seed/cover-skinwithkavya/1200/480', 7, 'Hyderabad', 'Telangana', 'India', 'female', '1997-02-26', '["Telugu", "English", "Hindi"]', 15000.00, 45000.00, 'INR', 4.40, 24, 68300, 355, 347, 27, 90.80, 2, 'available', 1, DATE_SUB(NOW(), INTERVAL 249 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 252 DAY), 83, 1.00, 'Kavya Reddy (@kavya.reddy.demo) - Beauty Creator in Hyderabad | Zusty', 'Shade matching for medium-to-deep Indian skin, because half the launches still stop three shades too light. Beauty collaborations from Rs.15,000.', DATE_SUB(NOW(), INTERVAL 254 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY)),
  (121, 2021, 'riddhi.shah.demo', 'Riddhi Shah', 'Bridal makeup artist in Surat', 'Working bridal MUA with 60+ weddings behind me, now bringing the kit breakdowns online - what survives a Gujarati wedding in May, what melts by the phera. New here, but every post is shot on a paying client with her permission.', 'https://picsum.photos/seed/cover-mua-riddhi/1200/480', 7, 'Surat', 'Gujarat', 'India', 'female', '2001-01-14', '["Gujarati", "Hindi", "English"]', 4000.00, 9800.00, 'INR', 4.70, 5, 8700, 215, 92, 9, 95.40, 3, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 9 DAY), 69, 1.00, 'Riddhi Shah (@riddhi.shah.demo) - Beauty Creator in Surat | Zusty', 'Working bridal MUA with 60+ weddings behind me, now bringing the kit breakdowns online. Beauty collaborations from Rs.4,000.', DATE_SUB(NOW(), INTERVAL 11 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (122, 2022, 'rohan.verma.demo', 'Rohan Verma', 'BGMI and Valorant, six nights a week', 'Six-hour live streams, a competitive roster, and the loudest Hindi-language FPS community on the platform. Peak concurrent viewership crosses 22,000 on tournament nights. Game launches, peripherals and energy brands get integration slots, not just a banner.', 'https://picsum.photos/seed/cover-rageplaysrohan/1200/480', 8, 'Mumbai', 'Maharashtra', 'India', 'male', '1996-12-30', '["Hindi", "English"]', 380000.00, 900000.00, 'INR', 4.70, 105, 1120000, 3519, 394, 110, 96.40, 4, 'available', 1, DATE_SUB(NOW(), INTERVAL 400 DAY), 1, DATE_ADD(NOW(), INTERVAL 60 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 403 DAY), 95, 1.50, 'Rohan Verma (@rohan.verma.demo) - Gaming Creator in Mumbai | Zusty', 'Six-hour live streams, a competitive roster, and the loudest Hindi-language FPS community on the platform. Gaming collaborations from Rs.380,000.', DATE_SUB(NOW(), INTERVAL 405 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (123, 2023, 'aisha.khan.demo', 'Aisha Khan', 'Casual gaming, zero gatekeeping', 'Mobile and console gaming for people who are bad at it and having fun anyway. Co-op nights with viewers, controller setups under Rs.5,000, and a deliberately friendly chat. Recently joined Zusty and taking on my first structured brand campaigns.', 'https://picsum.photos/seed/cover-noobqueen-aisha/1200/480', 8, 'Nagpur', 'Maharashtra', 'India', 'female', '1999-07-07', '["Hindi", "English"]', 22500.00, 57000.00, 'INR', 4.50, 9, 33600, 358, 146, 15, 95.00, 6, 'busy', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 22 DAY), 71, 1.00, 'Aisha Khan (@aisha.khan.demo) - Gaming Creator in Nagpur | Zusty', 'Mobile and console gaming for people who are bad at it and having fun anyway. Gaming collaborations from Rs.22,500.', DATE_SUB(NOW(), INTERVAL 24 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (124, 2024, 'amit.chourasia.demo', 'Amit Chourasia', 'Free Fire highlights and scrims', 'Tier-2 grind - Free Fire and BGMI scrims, clutch compilations and a weekly guide series in Hindi. Audience is 16-24 across MP, UP and Rajasthan, which is exactly where mobile-first brands underinvest.', 'https://picsum.photos/seed/cover-clutchkingamit/1200/480', 8, 'Indore', 'Madhya Pradesh', 'India', 'male', '1997-05-19', '["Hindi", "English"]', 111000.00, 260000.00, 'INR', 4.30, 33, 158000, 759, 201, 40, 93.60, 8, 'available', 1, DATE_SUB(NOW(), INTERVAL 271 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 274 DAY), 87, 1.00, 'Amit Chourasia (@amit.chourasia.demo) - Gaming Creator in Indore | Zusty', 'Tier-2 grind. Gaming collaborations from Rs.111,000.', DATE_SUB(NOW(), INTERVAL 276 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (125, 2025, 'meera.subramanian.demo', 'Meera Subramanian', 'Iyengar yoga and breathwork', 'Certified Iyengar teacher, sixteen years on the mat. Alignment-first sequences, pranayama for people who sit ten hours a day, and prop substitutes you already own. Wellness and Ayurveda brands reach a 30-50 audience here that buys for the long term.', 'https://picsum.photos/seed/cover-yogawithmeera/1200/480', 9, 'Kochi', 'Kerala', 'India', 'female', '1989-10-02', '["Malayalam", "English", "Hindi"]', 75000.00, 280000.00, 'INR', 4.90, 79, 204000, 930, 237, 87, 96.80, 12, 'available', 1, DATE_SUB(NOW(), INTERVAL 378 DAY), 1, DATE_ADD(NOW(), INTERVAL 30 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 381 DAY), 98, 1.40, 'Meera Subramanian (@meera.subramanian.demo) - Health & Wellness Creator in Kochi | Zusty', 'Certified Iyengar teacher, sixteen years on the mat. Health & Wellness collaborations from Rs.75,000.', DATE_SUB(NOW(), INTERVAL 383 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY)),
  (126, 2026, 'anuj.tripathi.demo', 'Anuj Tripathi', 'Everyday Ayurveda, plainly explained', 'BAMS graduate translating classical Ayurveda into things you can actually do on a Tuesday - dinacharya, seasonal food swaps, and why most of what you have been told about detox is wrong. Content in Hindi, sources cited.', 'https://picsum.photos/seed/cover-ayurvedaanuj/1200/480', 9, 'Bhopal', 'Madhya Pradesh', 'India', 'male', '1993-04-23', '["Hindi", "English"]', 17500.00, 45000.00, 'INR', 4.10, 12, 39800, 237, 219, 12, 88.20, 18, 'available', 0, NULL, 0, NULL, 'pending_review', NULL, NULL, NULL, 64, 0.80, 'Anuj Tripathi (@anuj.tripathi.demo) - Health & Wellness Creator in Bhopal | Zusty', 'BAMS graduate translating classical Ayurveda into things you can actually do on a Tuesday. Health & Wellness collaborations from Rs.17,500.', DATE_SUB(NOW(), INTERVAL 41 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY)),
  (127, 2027, 'tara.fernandes.demo', 'Tara Fernandes', 'Journaling, sleep and slow mornings', 'Guided journaling prompts, sleep hygiene, and a very quiet corner of the internet in Goa. New on Zusty with a small audience that shows up daily - my Sunday reset post has a 41 percent save rate.', 'https://picsum.photos/seed/cover-mindfulwithtara/1200/480', 9, 'Goa', 'Goa', 'India', 'female', '1998-09-12', '["English", "Konkani", "Hindi"]', 5000.00, 9800.00, 'INR', 4.80, 4, 6900, 175, 235, 8, 97.60, 24, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 7 DAY), 75, 1.00, 'Tara Fernandes (@tara.fernandes.demo) - Health & Wellness Creator in Goa | Zusty', 'Guided journaling prompts, sleep hygiene, and a very quiet corner of the internet in Goa. Health & Wellness collaborations from Rs.5,000.', DATE_SUB(NOW(), INTERVAL 9 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY)),
  (128, 2028, 'kabir.ranjan.demo', 'Kabir Ranjan', 'Sitar covers and raga explainers', 'Third-generation sitar player putting Hindustani classical next to film music - a raga explainer on Monday, a Bollywood cover on Friday. Instrument brands, audio gear and heritage campaigns fit naturally. Anything else does not, and I will say so.', 'https://picsum.photos/seed/cover-sitarwithkabir/1200/480', 10, 'Kolkata', 'West Bengal', 'India', 'male', '1992-06-14', '["Bengali", "Hindi", "English"]', 22500.00, 53000.00, 'INR', 4.60, 28, 54100, 349, 271, 33, 96.20, 2, 'available', 1, DATE_SUB(NOW(), INTERVAL 297 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 300 DAY), 82, 1.15, 'Kabir Ranjan (@kabir.ranjan.demo) - Music Creator in Kolkata | Zusty', 'Third-generation sitar player putting Hindustani classical next to film music. Music collaborations from Rs.22,500.', DATE_SUB(NOW(), INTERVAL 302 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (129, 2029, 'sana.mirza.demo', 'Sana Mirza', 'Independent music, unsigned and loud', 'Singer-songwriter and part-time A&R for the Indian indie scene. Original tracks, home-studio breakdowns, and a weekly feature on an unsigned artist. Audio brands and festivals get an audience that actually buys tickets.', 'https://picsum.photos/seed/cover-indieeveryday-sana/1200/480', 10, 'Mumbai', 'Maharashtra', 'India', 'female', '1996-03-05', '["Hindi", "English", "Urdu"]', 111000.00, 240000.00, 'INR', 4.70, 47, 187000, 775, 328, 53, 98.40, 3, 'busy', 1, DATE_SUB(NOW(), INTERVAL 342 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 345 DAY), 83, 1.20, 'Sana Mirza (@sana.mirza.demo) - Music Creator in Mumbai | Zusty', 'Singer-songwriter and part-time A&R for the Indian indie scene. Music collaborations from Rs.111,000.', DATE_SUB(NOW(), INTERVAL 347 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (130, 2030, 'prakash.yadav.demo', 'Prakash Yadav', 'JEE and NEET physics, free forever', 'Fourteen years of classroom teaching in Kanpur, now the full JEE and NEET physics syllabus free on YouTube. Twelve lakh students, most from tier-2 and tier-3 towns. Edtech, stationery and device brands reach a household decision, not just a teenager.', 'https://picsum.photos/seed/cover-physicswithprakash/1200/480', 11, 'Kanpur', 'Uttar Pradesh', 'India', 'male', '1988-01-29', '["Hindi", "English"]', 300000.00, 1050000.00, 'INR', 4.90, 214, 1450000, 4524, 668, 221, 96.80, 4, 'available', 1, DATE_SUB(NOW(), INTERVAL 413 DAY), 1, DATE_ADD(NOW(), INTERVAL 30 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 416 DAY), 96, 1.40, 'Prakash Yadav (@prakash.yadav.demo) - Education Creator in Kanpur | Zusty', 'Fourteen years of classroom teaching in Kanpur, now the full JEE and NEET physics syllabus free on YouTube. Education collaborations from Rs.300,000.', DATE_SUB(NOW(), INTERVAL 418 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (131, 2031, 'nandini.rao.demo', 'Nandini Rao', 'Spoken English and interview prep', 'Ex-corporate trainer teaching spoken English to first-generation graduates - interview answers, email etiquette, and pronunciation without an imported accent. Highest engagement comes from Bengaluru, Hyderabad and Coimbatore.', 'https://picsum.photos/seed/cover-englishwithnandini/1200/480', 11, 'Bengaluru', 'Karnataka', 'India', 'female', '1994-11-16', '["English", "Hindi", "Kannada"]', 17500.00, 65000.00, 'INR', 4.60, 35, 76800, 520, 349, 43, 94.20, 6, 'unavailable', 1, DATE_SUB(NOW(), INTERVAL 283 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 286 DAY), 85, 1.30, 'Nandini Rao (@nandini.rao.demo) - Education Creator in Bengaluru | Zusty', 'Ex-corporate trainer teaching spoken English to first-generation graduates. Education collaborations from Rs.17,500.', DATE_SUB(NOW(), INTERVAL 288 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (132, 2032, 'vivek.chauhan.demo', 'Vivek Chauhan', 'UPSC strategy from an interview-stage aspirant', 'Three attempts, two interview calls, and a very honest log of what worked and what wasted a year. Answer-writing breakdowns, current-affairs compilations and a weekly mentor call. Test-prep and publishing brands reach serious aspirants here.', 'https://picsum.photos/seed/cover-upscdiarieswithvivek/1200/480', 11, 'Delhi', 'Delhi', 'India', 'male', '1991-08-08', '["Hindi", "English"]', 93000.00, 180000.00, 'INR', 4.50, 30, 122000, 688, 120, 33, 94.00, 8, 'available', 1, DATE_SUB(NOW(), INTERVAL 254 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 257 DAY), 86, 1.15, 'Vivek Chauhan (@vivek.chauhan.demo) - Education Creator in Delhi | Zusty', 'Three attempts, two interview calls, and a very honest log of what worked and what wasted a year. Education collaborations from Rs.93,000.', DATE_SUB(NOW(), INTERVAL 259 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY)),
  (133, 2033, 'priya.jain.demo', 'Priya Jain', 'Personal finance for salaried India', 'CFA charterholder explaining tax regimes, SIPs and term insurance in plain Hindi. No stock tips, no calls, no lifetime-free-credit-card pitches. Fintech brands go through a compliance review with me before a single frame is shot.', 'https://picsum.photos/seed/cover-paisawithpriya/1200/480', 12, 'Mumbai', 'Maharashtra', 'India', 'female', '1992-05-21', '["Hindi", "English", "Marathi"]', 102000.00, 200000.00, 'INR', 4.80, 62, 231000, 799, 171, 66, 98.60, 12, 'available', 1, DATE_SUB(NOW(), INTERVAL 372 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 375 DAY), 87, 1.20, 'Priya Jain (@priya.jain.demo) - Finance Creator in Mumbai | Zusty', 'CFA charterholder explaining tax regimes, SIPs and term insurance in plain Hindi. Finance collaborations from Rs.102,000.', DATE_SUB(NOW(), INTERVAL 377 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY)),
  (134, 2034, 'manav.agarwal.demo', 'Manav Agarwal', 'Markets explained in Gujarati', 'Daily market wraps and balance-sheet basics in Gujarati for first-time investors in Ahmedabad, Rajkot and Surat. Building the page alongside a family broking practice, SEBI disclosures on every post.', 'https://picsum.photos/seed/cover-marketswithmanav/1200/480', 12, 'Ahmedabad', 'Gujarat', 'India', 'male', '1995-12-03', '["Gujarati", "Hindi", "English"]', 25000.00, 53000.00, 'INR', 4.00, 8, 44500, 285, 149, 10, 90.00, 18, 'available', 0, NULL, 0, NULL, 'pending_review', NULL, NULL, NULL, 64, 0.80, 'Manav Agarwal (@manav.agarwal.demo) - Finance Creator in Ahmedabad | Zusty', 'Daily market wraps and balance-sheet basics in Gujarati for first-time investors in Ahmedabad, Rajkot and Surat. Finance collaborations from Rs.25,000.', DATE_SUB(NOW(), INTERVAL 36 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY)),
  (135, 2035, 'nidhi.saxena.demo', 'Nidhi Saxena', 'Two kids, one very honest feed', 'Weaning charts, school-lunch rotations and the toys that survived a toddler. I test a product for at least three weeks before it appears on the page, and I have said no to more baby-care brands than I have said yes to.', 'https://picsum.photos/seed/cover-momlifewithnidhi/1200/480', 13, 'Lucknow', 'Uttar Pradesh', 'India', 'female', '1990-07-13', '["Hindi", "English"]', 15000.00, 57000.00, 'INR', 4.60, 27, 61700, 371, 177, 33, 93.20, 24, 'busy', 1, DATE_SUB(NOW(), INTERVAL 266 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 269 DAY), 80, 1.30, 'Nidhi Saxena (@nidhi.saxena.demo) - Parenting Creator in Lucknow | Zusty', 'Weaning charts, school-lunch rotations and the toys that survived a toddler. Parenting collaborations from Rs.15,000.', DATE_SUB(NOW(), INTERVAL 271 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (136, 2036, 'rahul.pillai.demo', 'Rahul Pillai', 'Hands-on dad, learning out loud', 'Documenting the unglamorous half of parenting - night feeds, hospital paperwork, and building a bunk bed badly. New to Zusty, small audience of fathers in their thirties who almost never get spoken to by brands.', 'https://picsum.photos/seed/cover-dadduty-rahul/1200/480', 13, 'Chennai', 'Tamil Nadu', 'India', 'male', '1989-02-18', '["Tamil", "English", "Hindi"]', 4000.00, 12200.00, 'INR', 4.40, 3, 7800, 247, 187, 10, 91.80, 2, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 19 DAY), 68, 1.00, 'Rahul Pillai (@rahul.pillai.demo) - Parenting Creator in Chennai | Zusty', 'Documenting the unglamorous half of parenting. Parenting collaborations from Rs.4,000.', DATE_SUB(NOW(), INTERVAL 21 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (137, 2037, 'ria.bhattacharya.demo', 'Ria Bhattacharya', 'Gentle parenting, Indian household edition', 'Child psychologist by training, mother of two by practice. Screen-time boundaries, tantrums in joint families, and what to say when a relative comments on your child''s weight. Long captions, deeply engaged saves.', 'https://picsum.photos/seed/cover-raisingriaa/1200/480', 13, 'Kolkata', 'West Bengal', 'India', 'female', '1991-10-27', '["Bengali", "Hindi", "English"]', 93000.00, 280000.00, 'INR', 4.50, 34, 134000, 654, 243, 42, 94.00, 3, 'unavailable', 1, DATE_SUB(NOW(), INTERVAL 305 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 308 DAY), 82, 1.20, 'Ria Bhattacharya (@ria.bhattacharya.demo) - Parenting Creator in Kolkata | Zusty', 'Child psychologist by training, mother of two by practice. Parenting collaborations from Rs.93,000.', DATE_SUB(NOW(), INTERVAL 310 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (138, 2038, 'vikram.rathore.demo', 'Vikram Rathore', 'Motorcycles, tested on real roads', 'Every motorcycle gets 1,000 km on Rajasthan highways and Jaipur traffic before I review it. Real mileage, real service costs, real pillion feedback. Tyre, helmet and lubricant brands get a mechanic''s-eye teardown, not a montage.', 'https://picsum.photos/seed/cover-throttletalesvikram/1200/480', 14, 'Jaipur', 'Rajasthan', 'India', 'male', '1993-09-06', '["Hindi", "English", "Rajasthani"]', 102000.00, 180000.00, 'INR', 4.70, 55, 289000, 1145, 306, 58, 97.40, 4, 'available', 1, DATE_SUB(NOW(), INTERVAL 353 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 356 DAY), 83, 1.25, 'Vikram Rathore (@vikram.rathore.demo) - Automobile Creator in Jaipur | Zusty', 'Every motorcycle gets 1,000 km on Rajasthan highways and Jaipur traffic before I review it. Automobile collaborations from Rs.102,000.', DATE_SUB(NOW(), INTERVAL 358 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (139, 2039, 'krishna.menon.demo', 'Krishna Menon', 'EV ownership, month by month', 'Three years and 48,000 km on electric two-wheelers and a compact EV car. Charging-network maps, monsoon range loss, and the actual cost per kilometre from my own spreadsheet. The most-asked question I get is about resale, so I track that too.', 'https://picsum.photos/seed/cover-evwithkrishna/1200/480', 14, 'Bengaluru', 'Karnataka', 'India', 'male', '1994-04-15', '["Malayalam", "English", "Kannada"]', 25000.00, 49000.00, 'INR', 4.30, 19, 58200, 501, 272, 23, 93.60, 6, 'available', 1, DATE_SUB(NOW(), INTERVAL 227 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 230 DAY), 84, 1.00, 'Krishna Menon (@krishna.menon.demo) - Automobile Creator in Bengaluru | Zusty', 'Three years and 48,000 km on electric two-wheelers and a compact EV car. Automobile collaborations from Rs.25,000.', DATE_SUB(NOW(), INTERVAL 232 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY)),
  (140, 2040, 'manya.sood.demo', 'Manya Sood', 'Women who ride, in the north', 'Riding a 390 through Himachal and running beginner rider meet-ups for women in Chandigarh. New on Zusty with a small, extremely loyal community and a gear-review series aimed at riders under 5''4".', 'https://picsum.photos/seed/cover-bikergirlmanya/1200/480', 14, 'Chandigarh', 'Chandigarh', 'India', 'female', '1998-11-24', '["Hindi", "Punjabi", "English"]', 3000.00, 10600.00, 'INR', 4.90, 5, 9600, 148, 284, 10, 96.80, 8, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 12 DAY), 72, 1.00, 'Manya Sood (@manya.sood.demo) - Automobile Creator in Chandigarh | Zusty', 'Riding a 390 through Himachal and running beginner rider meet-ups for women in Chandigarh. Automobile collaborations from Rs.3,000.', DATE_SUB(NOW(), INTERVAL 14 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY)),
  (141, 2041, 'sahil.kapadia.demo', 'Sahil Kapadia', 'Observational comedy about office India', 'Sketches about appraisal season, group projects and the uncle who forwards everything. Written and shot with a four-person crew, two uploads a week, and brand integrations that people actually rewatch. Ten years of open mics before any of this worked.', 'https://picsum.photos/seed/cover-sarcasmbysahil/1200/480', 15, 'Mumbai', 'Maharashtra', 'India', 'male', '1994-08-31', '["Hindi", "English", "Gujarati"]', 340000.00, 975000.00, 'INR', 4.80, 141, 1680000, 5096, 726, 147, 96.60, 12, 'available', 1, DATE_SUB(NOW(), INTERVAL 407 DAY), 1, DATE_ADD(NOW(), INTERVAL 45 DAY), 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 410 DAY), 93, 1.45, 'Sahil Kapadia (@sahil.kapadia.demo) - Comedy Creator in Mumbai | Zusty', 'Sketches about appraisal season, group projects and the uncle who forwards everything. Comedy collaborations from Rs.340,000.', DATE_SUB(NOW(), INTERVAL 412 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY)),
  (142, 2042, 'ira.bose.demo', 'Ira Bose', 'Relatable chaos, 45 seconds at a time', 'Every character on the page is somebody''s cousin - the wedding aunty, the hostel roommate, the WhatsApp group admin. Fast turnaround, three scripts per brief, and I will happily rewrite until the joke lands rather than reading a tagline.', 'https://picsum.photos/seed/cover-desidramaqueen-ira/1200/480', 15, 'Pune', 'Maharashtra', 'India', 'female', '1996-01-07', '["Hindi", "English", "Bengali"]', 93000.00, 260000.00, 'INR', 4.60, 43, 165000, 675, 371, 50, 95.20, 18, 'available', 1, DATE_SUB(NOW(), INTERVAL 319 DAY), 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 322 DAY), 87, 1.25, 'Ira Bose (@ira.bose.demo) - Comedy Creator in Pune | Zusty', 'Every character on the page is somebody''s cousin. Comedy collaborations from Rs.93,000.', DATE_SUB(NOW(), INTERVAL 324 DAY), DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (143, 2043, 'gurmeet.brar.demo', 'Gurmeet Brar', 'Punjabi stand-up, clipped for reels', 'Stand-up sets in Punjabi and Hindi from Delhi rooms, cut into reels that travel across Punjab, Haryana and the diaspora. Recently on Zusty and open to regional-language brand campaigns.', 'https://picsum.photos/seed/cover-punjabipunchesgurmeet/1200/480', 15, 'Delhi', 'Delhi', 'India', 'male', '1997-07-20', '["Punjabi", "Hindi", "English"]', 22500.00, 65000.00, 'INR', 4.50, 7, 27400, 305, 96, 15, 95.00, 24, 'unavailable', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 25 DAY), 75, 1.00, 'Gurmeet Brar (@gurmeet.brar.demo) - Comedy Creator in Delhi | Zusty', 'Stand-up sets in Punjabi and Hindi from Delhi rooms, cut into reels that travel across Punjab, Haryana and the diaspora. Comedy collaborations from Rs.22,500.', DATE_SUB(NOW(), INTERVAL 27 DAY), DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (144, 2044, 'anushka.pathak.demo', 'Anushka Pathak', 'Ink illustration and lettering', 'Pen-and-ink illustration, Devanagari lettering and slow process videos that people leave running in the background. Stationery and art-supply brands get an honest tooth-and-bleed test on camera. New to Zusty, portfolio built over five years.', 'https://picsum.photos/seed/cover-inkbyanushka/1200/480', 16, 'Bhopal', 'Madhya Pradesh', 'India', 'female', '1999-03-11', '["Hindi", "English"]', 25000.00, 45000.00, 'INR', 4.70, 10, 31900, 353, 121, 13, 98.40, 2, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 14 DAY), 68, 1.00, 'Anushka Pathak (@anushka.pathak.demo) - Art & Design Creator in Bhopal | Zusty', 'Pen-and-ink illustration, Devanagari lettering and slow process videos that people leave running in the background. Art & Design collaborations from Rs.25,000.', DATE_SUB(NOW(), INTERVAL 16 DAY), DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (145, 2045, 'sameer.qadri.demo', 'Sameer Qadri', 'Product design breakdowns', 'Deconstructing Indian app interfaces and packaging design - what works, what is a dark pattern, and how I would redraw it. Just joined Zusty, and the audience is small but almost entirely working designers and founders.', 'https://picsum.photos/seed/cover-designdiarysameer/1200/480', 16, 'Surat', 'Gujarat', 'India', 'male', '1996-09-29', '["Gujarati", "Hindi", "English", "Urdu"]', 3000.00, 9800.00, 'INR', 4.20, 4, 8300, 319, 140, 8, 88.40, 3, 'available', 0, NULL, 0, NULL, 'approved', NULL, 1, DATE_SUB(NOW(), INTERVAL 4 DAY), 69, 1.00, 'Sameer Qadri (@sameer.qadri.demo) - Art & Design Creator in Surat | Zusty', 'Deconstructing Indian app interfaces and packaging design. Art & Design collaborations from Rs.3,000.', DATE_SUB(NOW(), INTERVAL 6 DAY), DATE_SUB(NOW(), INTERVAL 3 DAY))
